def count_substrings(s, substr):
    count = 0
    start = 0
    while True:
        start = s.find(substr, start)
        if start == -1:
            break
        count += 1
        start += 1
    return count

def main():
    T = int(input())
    results = []
    for _ in range(T):
        A = input().strip()
        B = input().strip()
        N = int(input())
        favorite_strings = []
        for _ in range(N):
            S, b = input().strip().split()
            favorite_strings.append((S, int(b)))

        max_pleasure = 0
        for i in range(len(A)):
            for j in range(len(B)):
                C = A[i:] + B[j:]
                pleasure = 0
                for S, b in favorite_strings:
                    cnt = count_substrings(C, S)
                    pleasure += cnt * b
                max_pleasure = max(max_pleasure, pleasure)
        results.append(max_pleasure)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
